#include <affresco/affresco.hpp>
#include "Station.hpp"

// A weather station: the UI is a live document, the readings come from C++
int main() {
    affresco::Application app;
    affresco::Screen screen = affresco::Screen::fromFile("screens/station.screen.json");
    screen.createWindow(app);

    Station station(screen);
    // TODO: read the sensor's name from the settings
    station.connect("sensor-0");
    return app.run();
}

#pragma once

#include <affresco/Screen.hpp>
#include <string>

/// @brief Reads the sensors and puts their values in the screen's state.
class Station {
public:
    explicit Station(affresco::Screen& screen);

    /// @brief Starts reading the sensor with this name.
    void connect(const std::string& sensor);

private:
    affresco::Screen& screen_; ///< The station's live document.
    double lastCelsius_ = 0.0; ///< The last temperature read.
};

#include "Station.hpp"

Station::Station(affresco::Screen& screen) : screen_(screen) {}

void Station::connect(const std::string& sensor) {
    // FIXME: a sensor that never answers blocks the UI thread
    lastCelsius_ = sensor0(readRaw(sensor));
    screen_.applyRevision(R"({"message": "New reading",
        "patch": [{"op": "replace", "path": "/state/celsius", "value": 21.5}]})");
}

